mapper.select:
SELECT i.id, i.title, i.author, i.summary, i.views, i.likes, i.collects, i.publish_date AS `date`, c.code AS category, c.name AS categoryName, co.name AS companyName, co.avatar_text AS avatar, co.avatar_color AS avatarColor, GROUP_CONCAT(DISTINCT t.name ORDER BY t.id ASC SEPARATOR ',') AS tagsStr FROM interview i JOIN category c ON i.category_id = c.id JOIN company co ON i.company_id = co.id LEFT JOIN interview_tag it ON i.id = it.interview_id LEFT JOIN tag t ON it.tag_id = t.id WHERE i.status = 1
AND c.code = #{category}
AND (i.title LIKE CONCAT('%', #{keyword}, '%') OR i.author LIKE CONCAT('%', #{keyword}, '%') OR i.summary LIKE CONCAT('%', #{keyword}, '%'))
GROUP BY i.id, i.title, i.author, i.summary, i.views, i.likes, i.collects, i.publish_date, c.code, c.name, co.name, co.avatar_text, co.avatar_color ORDER BY i.publish_date DESC, i.likes DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM interview i JOIN category c ON i.category_id = c.id WHERE i.status = 1
AND c.code = #{category}
AND (i.title LIKE CONCAT('%', #{keyword}, '%') OR i.author LIKE CONCAT('%', #{keyword}, '%') OR i.summary LIKE CONCAT('%', #{keyword}, '%'))

SELECT id, likes, collects
FROM interview
WHERE id = #{id}
